def ev(e):
    s = []
    for t in e.split():
        if t.isdigit():
            s.append(int(t))
        else:
            b = s.pop()
            a = s.pop()
            if t == '+': s.append(a + b)
            elif t == '-': s.append(a - b)
            elif t == '*': s.append(a * b)
            else: s.append(a // b)
    return s.pop()
